AI Prototype Summary
The purpose of the AI Prototype is to experiment with utilizing AI as a coding assistant, and analyze the quality, speed, and precision that an LLM can generate code. The prompt for this week is shown below:






TipAI Prototypes (Claude, incognito mode, Sonnet 5, high reasoning effort)



“Write SystemVerilog HDL to time multiplex a single seven segment decoder (that decodes from four bits to a common anode seven segment display) to decode two sets of input bits and drive two sets of seven output bits.”








TipAI Prototypes (Claude, incognito mode, Sonnet 5, high reasoning effort, lab 1 counter.sv and seven_seg_decoder.sv attached as context)



“Write SystemVerilog HDL to time multiplex a single seven segment decoder (that decodes from four bits to a common anode seven segment display) to decode two sets of input bits and drive two sets of seven output bits. Use the seven segment decoder and oscillator provided in the attached files.”








NoteGenerated code, prompt 1





// =============================================================================
// seg7_decode
// Combinational 4-bit binary to seven-segment decoder.
// Common anode display, active-low segment outputs.
// Segment bit order: seg[6:0] = {g, f, e, d, c, b, a}
// =============================================================================
module seg7_decode (
    input  logic [3:0] value,
    output logic [6:0] seg
);

    always_comb begin
        unique case (value)
            4'h0:    seg = 7'b1000000;
            4'h1:    seg = 7'b1111001;
            4'h2:    seg = 7'b0100100;
            4'h3:    seg = 7'b0110000;
            4'h4:    seg = 7'b0011001;
            4'h5:    seg = 7'b0010010;
            4'h6:    seg = 7'b0000010;
            4'h7:    seg = 7'b1111000;
            4'h8:    seg = 7'b0000000;
            4'h9:    seg = 7'b0010000;
            4'hA:    seg = 7'b0001000;
            4'hB:    seg = 7'b0000011;
            4'hC:    seg = 7'b1000110;
            4'hD:    seg = 7'b0100001;
            4'hE:    seg = 7'b0000110;
            4'hF:    seg = 7'b0001110;
            default: seg = 7'b1111111;
        endcase
    end

endmodule

// =============================================================================
// seg7_time_mux2
// Time-multiplexes a single seg7_decode instance across two 4-bit inputs.
// Each output bus is registered and holds its decoded value between
// updates, so both displays remain static rather than blinking.
// =============================================================================
module seg7_time_mux2 (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] value0,
    input  logic [3:0] value1,
    output logic [6:0] seg0,
    output logic [6:0] seg1
);

    logic       sel;
    logic [3:0] value_mux;
    logic [6:0] seg_dec;

    assign value_mux = sel ? value1 : value0;

    seg7_decode u_seg7_decode (
        .value (value_mux),
        .seg   (seg_dec)
    );

    always_ff @(posedge clk) begin
        if (rst) begin
            sel  &lt;= 1'b0;
            seg0 &lt;= 7'b1111111;
            seg1 &lt;= 7'b1111111;
        end else begin
            sel &lt;= ~sel;
            if (sel) begin
                seg1 &lt;= seg_dec;
            end else begin
                seg0 &lt;= seg_dec;
            end
        end
    end

endmodule









NoteGenerated code, prompt 2 (with lab 1 files attached)





module seven_seg_mux #(
    parameter int N = 17,
    parameter logic [N-1:0] MAX = 17'd99_999
) (
    input  logic       clk,
    input  logic       rst,

    input  logic [3:0] digit0,
    input  logic [3:0] digit1,

    output logic [6:0] seg,
    output logic [1:0] an
);

    logic [N-1:0] refresh_count;
    logic         refresh_tick;
    logic         digit_sel;
    logic [3:0]   digit_mux;

    counter #(
        .N   (N),
        .MAX (MAX)
    ) refresh_counter (
        .clk (clk),
        .rst (rst),
        .en  (1'b1),
        .q   (refresh_count)
    );

    assign refresh_tick = (refresh_count == MAX);

    counter #(
        .N   (1),
        .MAX (1'b1)
    ) digit_sel_counter (
        .clk (clk),
        .rst (rst),
        .en  (refresh_tick),
        .q   (digit_sel)
    );

    assign digit_mux = digit_sel ? digit1 : digit0;

    seven_seg_decoder decoder (
        .s   (digit_mux),
        .seg (seg)
    );

    always_comb begin
        an            = 2'b11;
        an[digit_sel] = 1'b0;
    end

endmodule



Reflection: Without any lab context, the first prompt’s design time-multiplexed the decoder’s combinational logic, but latched the two digits onto two entirely separate 7-bit output buses, an architecture that only works if the board exposes two independent segment buses rather than the single, anode-multiplexed bus we use in this lab. It did mention that a shared bus would instead need a slow anode-select clock divider, but did not generate that version. With lab 1’s counter and seven_seg_decoder modules attached as context, the second prompt generated two instances of the existing counter module (one free-running for the refresh period, one a 1-bit toggle clocked by the first’s terminal count) driving a single seven_seg_decoder instance through a 2:1 mux, with an[1:0] selecting the active digit. Giving the model the actual modules to reuse, rather than describing the goal in the abstract, got the LLM to infer the actual physical constraint (one shared segment bus).

AI Prototype Summary
The purpose of the AI Prototype is to experiment with utilizing AI as a coding assistant, and analyze the quality, speed, and precision that an LLM can generate code. The prompt for this week is shown below:






TipAI Prototype (Claude, incognito mode, Sonnet 5, high reasoning effort)



Prompt: “Write SystemVerilog HDL to leverage the internal high speed oscillator in the Lattice UP5K FPGA and blink an LED at 2 Hz. Take full advantage of SystemVerilog syntax, for example, using logic instead of wire and reg.”








NoteGenerated Code (first attempt)





//------------------------------------------------------------------------
// led_blink_2hz.sv
//
// Blinks an LED at BLINK_FREQ_HZ using the UP5K internal high-frequency
// oscillator (SB_HFOSC) as the sole clock source. No external clock or
// reset input is required; on an SRAM-based iCE40 device, all flip-flops
// power up to the state defined at synthesis (0 by default), so `count`
// and `led` both start at 0 without an explicit reset path.
//------------------------------------------------------------------------

module led_blink_2hz #(
    // CLK_FREQ_HZ must match the CLKHF_DIV setting on the SB_HFOSC
    // instance below:
    //   "0b00" = 48 MHz (default)   "0b01" = 24 MHz
    //   "0b10" = 12 MHz             "0b11" = 6 MHz
    parameter int CLK_FREQ_HZ   = 12_000_000,
    parameter int BLINK_FREQ_HZ = 2
) (
    output logic led
);

    //----------------------------------------------------------------------
    // Internal high-frequency oscillator
    //----------------------------------------------------------------------
    logic clk;

    SB_HFOSC #(
        .CLKHF_DIV("0b10")
    ) u_hfosc (
        .CLKHFPU(1'b1),
        .CLKHFEN(1'b1),
        .CLKHF  (clk)
    );

    //----------------------------------------------------------------------
    // Toggle counter: one toggle every quarter blink period
    //----------------------------------------------------------------------
    localparam int TOGGLE_COUNT = CLK_FREQ_HZ / (BLINK_FREQ_HZ * 2);
    localparam int CNT_WIDTH    = $clog2(TOGGLE_COUNT);

    logic [CNT_WIDTH-1:0] count;

    always_ff @(posedge clk) begin
        if (count == TOGGLE_COUNT - 1) begin
            count &lt;= '0;
            led   &lt;= ~led;
        end else begin
            count &lt;= count + 1'b1;
        end
    end

endmodule



This first version failed to synthesize in Lattice Radiant:
35901063  Error  ../../led_blink_2hz.sv(36): instantiating unknown module SB_HFOSC. VERI-1063  [led_blink_2hz.sv:36]
I gave Claude the error with no other context and it provided a reasonable explanation for the issue: SB_HFOSC is the name used by the older iCEcube2 and the open-source Yosys/nextpnr toolchains, while Lattice Radiant only recognizes the oscillator under the name HSOSC. It also suggested that if the CLKHF_DIV string literal "0b10" were ever rejected, the vector form 2'b10 was worth trying instead, since Lattice’s own examples use both notations inconsistently. It then returned a corrected version with the primitive renamed and a comment explaining the change.






NoteGenerated Code (corrected)





//------------------------------------------------------------------------
// led_blink_2hz.sv
//
// Blinks an LED at BLINK_FREQ_HZ using the UP5K internal high-frequency
// oscillator (SB_HFOSC) as the sole clock source. No external clock or
// reset input is required; on an SRAM-based iCE40 device, all flip-flops
// power up to the state defined at synthesis (0 by default), so `count`
// and `led` both start at 0 without an explicit reset path.
//------------------------------------------------------------------------

module led_blink_2hz #(
    // CLK_FREQ_HZ must match the CLKHF_DIV setting on the SB_HFOSC
    // instance below:
    //   "0b00" = 48 MHz (default)   "0b01" = 24 MHz
    //   "0b10" = 12 MHz             "0b11" = 6 MHz
    parameter int CLK_FREQ_HZ   = 12_000_000,
    parameter int BLINK_FREQ_HZ = 2
) (
    output logic led
);

    //----------------------------------------------------------------------
    // Internal high-frequency oscillator
    //----------------------------------------------------------------------
    logic clk;

    // Lattice Radiant names this primitive HSOSC; the older iCEcube2
    // toolchain and the open-source Yosys/nextpnr flow use SB_HFOSC
    // instead. Port names (CLKHFPU, CLKHFEN, CLKHF) are identical
    // between the two.
    HSOSC #(
        .CLKHF_DIV("0b10")
    ) u_hfosc (
        .CLKHFPU(1'b1),
        .CLKHFEN(1'b1),
        .CLKHF  (clk)
    );

    //----------------------------------------------------------------------
    // Toggle counter: one toggle every quarter blink period
    //----------------------------------------------------------------------
    localparam int TOGGLE_COUNT = CLK_FREQ_HZ / (BLINK_FREQ_HZ * 2);
    localparam int CNT_WIDTH    = $clog2(TOGGLE_COUNT);

    logic [CNT_WIDTH-1:0] count;

    always_ff @(posedge clk) begin
        if (count == TOGGLE_COUNT - 1) begin
            count &lt;= '0;
            led   &lt;= ~led;
        end else begin
            count &lt;= count + 1'b1;
        end
    end

endmodule



Reflection: The corrected code synthesized successfully in Lattice Radiant on the second attempt. In terms of quality, the output seems clean and idiomatic: it used logic, parameterized the clock frequency and blink frequency, derived the counter width with $clog2, and used underscore-separated numeric literals for readability. However, for my preferences, I find the amount of comments excessive.
The mistake Claude made was assuming the open-source Yosys/nextpnr primitive name (SB_HFOSC) would be used instead of Lattice Radiant’s (HSOSC). Ideally, Claude would predict that issue in advance and ask which toolchain was in use before generating any code. However, I also could have provided the information about the toolchain myself, and I would normally do so if I were to ask an LLM to generate code like this.

AI Prototype Summary
The purpose of the AI Prototype is to experiment with utilizing AI as a coding assistant, and analyze the quality, speed, and precision that an LLM can generate code.






TipPrototype A: monolithic prompt (Claude, Opus 5.5, high reasoning effort)





Target device: Lattice iCE40 UP5K FPGA with internal high-speed oscillator (~20 MHz).
Write synthesizable SystemVerilog to scan a 4x4 matrix keypad and display the last two hex keys pressed on a dual 7-segment display. Implement:

A clock divider that derives a scan clock on the order of 100-200 Hz from the internal oscillator.
A keypad scanning controller that iterates one active-low column at a time and samples active-low rows, registering at most one key per press (debounce-by-design), ignoring additional presses while any key is held, and allowing a new registration only after release.
A top level that updates two hex digits (older and most recent) when a new key is registered and drives a time-multiplexed two-digit 7-segment display without visible flicker and with balanced brightness.

Use idiomatic SystemVerilog (e.g., logic, always_ff, enumerated states for FSMs). Provide clean module boundaries and keep all state synchronous. Include brief comments explaining the design choices.









NotePrototype A generated code





// ============================================================================
// 4x4 keypad scanner with two-digit multiplexed hexadecimal display
// Target: Lattice iCE40 UP5K, internal high-frequency oscillator (HSOSC)
// ============================================================================

// ----------------------------------------------------------------------------
// sync_2ff
// Two-flop synchronizer for asynchronous inputs. Bits are synchronized
// independently. Incoherence between bits is harmless here: any mix of old
// and new row values is itself a valid keypad state, and the scanner
// resolves it on a later scan.
// ----------------------------------------------------------------------------
module sync_2ff #(
    parameter int unsigned WIDTH = 1
) (
    input  logic             clk,
    input  logic [WIDTH-1:0] d,
    output logic [WIDTH-1:0] q
);

  logic [WIDTH-1:0] meta;

  always_ff @(posedge clk) begin
    meta &lt;= d;
    q    &lt;= meta;
  end

endmodule

// ----------------------------------------------------------------------------
// tick_gen
// Produces a one-cycle enable pulse at TICK_HZ. An enable is used instead of
// a divided clock so that all registers remain in the single oscillator
// domain on the global clock network (no fabric-routed derived clock, no
// second clock domain, no clock-domain crossing).
// ----------------------------------------------------------------------------
module tick_gen #(
    parameter int unsigned CLK_HZ  = 24_000_000,
    parameter int unsigned TICK_HZ = 200
) (
    input  logic clk,
    input  logic rst,
    output logic tick
);

  localparam int unsigned DIV = CLK_HZ / TICK_HZ;
  localparam int unsigned CW  = (DIV &gt; 1) ? $clog2(DIV) : 1;

  logic [CW-1:0] count;

  always_ff @(posedge clk) begin
    if (rst) begin
      count &lt;= '0;
      tick  &lt;= 1'b0;
    end else if (count == CW'(DIV - 1)) begin
      count &lt;= '0;
      tick  &lt;= 1'b1;
    end else begin
      count &lt;= count + 1'b1;
      tick  &lt;= 1'b0;
    end
  end

endmodule

// ----------------------------------------------------------------------------
// keypad_scanner
// Drives one active-low column per scan tick and samples the active-low
// rows at the end of that column's dwell time.
//
//   ARMED : the first active row found registers exactly one key
//           (single-cycle key_valid pulse) and the FSM moves to LOCKED.
//   LOCKED: scanning continues over all columns but nothing is registered.
//           The FSM re-arms only after RELEASE_SCANS consecutive full scans
//           with no active row, i.e. after every key has been released.
//
// Debounce by design: each key is sampled once per full scan (4 ticks,
// 20 ms at 200 Hz), which exceeds typical contact bounce. Press bounce is
// masked by the lock; release bounce is masked by requiring consecutive
// clean scans before re-arming. RELEASE_SCANS must be at least 1.
// ----------------------------------------------------------------------------
module keypad_scanner #(
    parameter int unsigned RELEASE_SCANS = 2
) (
    input  logic       clk,
    input  logic       rst,
    input  logic       scan_tick,
    input  logic [3:0] row_n,
    output logic [3:0] col_n,
    output logic       key_valid,
    output logic [3:0] key_code
);

  typedef enum logic {
    ARMED,
    LOCKED
  } state_t;

  localparam logic [1:0]  LAST_COL = 2'd3;
  localparam int unsigned RW       = (RELEASE_SCANS &gt; 1) ?
                                     $clog2(RELEASE_SCANS) : 1;

  state_t        state;
  logic [1:0]    col_idx;
  logic [1:0]    col_next;
  logic [1:0]    row_idx;
  logic          row_hit;
  logic          press_seen;
  logic [RW-1:0] clean_scans;

  // Key layout (row 0 at top, column 0 at left):
  //   1 2 3 A
  //   4 5 6 B
  //   7 8 9 C
  //   E 0 F D   (* maps to E, # maps to F)
  function automatic logic [3:0] key_map(input logic [1:0] row,
                                         input logic [1:0] col);
    unique case ({row, col})
      4'h0: return 4'h1;
      4'h1: return 4'h2;
      4'h2: return 4'h3;
      4'h3: return 4'hA;
      4'h4: return 4'h4;
      4'h5: return 4'h5;
      4'h6: return 4'h6;
      4'h7: return 4'hB;
      4'h8: return 4'h7;
      4'h9: return 4'h8;
      4'hA: return 4'h9;
      4'hB: return 4'hC;
      4'hC: return 4'hE;
      4'hD: return 4'h0;
      4'hE: return 4'hF;
      4'hF: return 4'hD;
    endcase
  endfunction

  assign col_next = col_idx + 2'd1;
  assign row_hit  = ~&row_n;

  // Lowest-numbered active row wins if several rows are active.
  always_comb begin
    casez (row_n)
      4'b???0: row_idx = 2'd0;
      4'b??01: row_idx = 2'd1;
      4'b?011: row_idx = 2'd2;
      default: row_idx = 2'd3;
    endcase
  end

  // --- Column sequencer ------------------------------------------------------
  // col_n is registered and always equals the decode of col_idx, so at each
  // tick the synchronized rows reflect the column driven for the full
  // preceding dwell period.
  always_ff @(posedge clk) begin
    if (rst) begin
      col_idx &lt;= 2'd0;
      col_n   &lt;= 4'b1110;
    end else if (scan_tick) begin
      col_idx &lt;= col_next;
      col_n   &lt;= ~(4'b0001 &lt;&lt; col_next);
    end
  end

  // --- Registration FSM ------------------------------------------------------
  always_ff @(posedge clk) begin
    if (rst) begin
      state       &lt;= ARMED;
      press_seen  &lt;= 1'b0;
      clean_scans &lt;= '0;
      key_valid   &lt;= 1'b0;
      key_code    &lt;= 4'h0;
    end else begin
      key_valid &lt;= 1'b0;
      if (scan_tick) begin
        unique case (state)
          ARMED: begin
            if (row_hit) begin
              state       &lt;= LOCKED;
              key_valid   &lt;= 1'b1;
              key_code    &lt;= key_map(row_idx, col_idx);
              clean_scans &lt;= '0;
              // Mark the current partial scan as dirty so it cannot count
              // toward release before the pressed column is re-sampled.
              press_seen  &lt;= (col_idx != LAST_COL);
            end
          end

          LOCKED: begin
            if (col_idx == LAST_COL) begin
              press_seen &lt;= 1'b0;
              if (press_seen || row_hit) begin
                clean_scans &lt;= '0;
              end else if (clean_scans == RW'(RELEASE_SCANS - 1)) begin
                state       &lt;= ARMED;
                clean_scans &lt;= '0;
              end else begin
                clean_scans &lt;= clean_scans + 1'b1;
              end
            end else begin
              press_seen &lt;= press_seen | row_hit;
            end
          end
        endcase
      end
    end
  end

endmodule

// ----------------------------------------------------------------------------
// hex_to_seg
// Hexadecimal to seven-segment decoder. seg = {g, f, e, d, c, b, a},
// active high. Polarity for the physical display is applied at the top.
// ----------------------------------------------------------------------------
module hex_to_seg (
    input  logic [3:0] hex,
    output logic [6:0] seg
);

  always_comb begin
    unique case (hex)
      4'h0: seg = 7'b011_1111;
      4'h1: seg = 7'b000_0110;
      4'h2: seg = 7'b101_1011;
      4'h3: seg = 7'b100_1111;
      4'h4: seg = 7'b110_0110;
      4'h5: seg = 7'b110_1101;
      4'h6: seg = 7'b111_1101;
      4'h7: seg = 7'b000_0111;
      4'h8: seg = 7'b111_1111;
      4'h9: seg = 7'b110_1111;
      4'hA: seg = 7'b111_0111;
      4'hB: seg = 7'b111_1100;
      4'hC: seg = 7'b011_1001;
      4'hD: seg = 7'b101_1110;
      4'hE: seg = 7'b111_1001;
      4'hF: seg = 7'b111_0001;
    endcase
  end

endmodule

// ----------------------------------------------------------------------------
// display_mux
// Time-multiplexes two digits over shared segment lines. Each digit owns an
// identical slot of SLOT_CYCLES clocks, so both digits receive the same duty
// cycle and therefore the same brightness. The first BLANK_CYCLES of every
// slot disable all digits and segments so the previous digit driver turns
// off completely before new segment data appears (prevents ghosting).
// SLOT_HZ = 1 kHz yields a 500 Hz refresh per digit, well above the flicker
// fusion threshold. Outputs are active high and registered.
// ----------------------------------------------------------------------------
module display_mux #(
    parameter int unsigned CLK_HZ    = 24_000_000,
    parameter int unsigned SLOT_HZ   = 1_000,
    parameter int unsigned BLANK_DIV = 32
) (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] hex_left,
    input  logic [3:0] hex_right,
    output logic [6:0] seg,
    output logic [1:0] digit_en
);

  localparam int unsigned SLOT_CYCLES  = CLK_HZ / SLOT_HZ;
  localparam int unsigned BLANK_CYCLES = SLOT_CYCLES / BLANK_DIV;
  localparam int unsigned CW           = (SLOT_CYCLES &gt; 1) ?
                                         $clog2(SLOT_CYCLES) : 1;

  logic [CW-1:0] count;
  logic          sel_left;
  logic          blank;
  logic [6:0]    seg_left;
  logic [6:0]    seg_right;

  hex_to_seg u_seg_left (
      .hex(hex_left),
      .seg(seg_left)
  );

  hex_to_seg u_seg_right (
      .hex(hex_right),
      .seg(seg_right)
  );

  assign blank = (count &lt; CW'(BLANK_CYCLES));

  always_ff @(posedge clk) begin
    if (rst) begin
      count    &lt;= '0;
      sel_left &lt;= 1'b0;
    end else if (count == CW'(SLOT_CYCLES - 1)) begin
      count    &lt;= '0;
      sel_left &lt;= ~sel_left;
    end else begin
      count &lt;= count + 1'b1;
    end
  end

  always_ff @(posedge clk) begin
    if (rst) begin
      seg      &lt;= 7'b000_0000;
      digit_en &lt;= 2'b00;
    end else if (blank) begin
      seg      &lt;= 7'b000_0000;
      digit_en &lt;= 2'b00;
    end else if (sel_left) begin
      seg      &lt;= seg_left;
      digit_en &lt;= 2'b10;
    end else begin
      seg      &lt;= seg_right;
      digit_en &lt;= 2'b01;
    end
  end

endmodule

// ----------------------------------------------------------------------------
// keypad_display_top
// Displays the two most recently registered keys: older on the left digit
// (digit[1]), most recent on the right digit (digit[0]).
//
// Columns are driven open-drain (low or high-Z) so that two keys pressed in
// the same row cannot short a high column to a low column. Rows require
// pull-ups (internal I/O pull-ups or external resistors).
//
// CLK_HZ must match CLKHF_DIV: "0b00" = 48, "0b01" = 24, "0b10" = 12,
// "0b11" = 6 MHz (nominal).
// ----------------------------------------------------------------------------
module keypad_display_top #(
    parameter int unsigned CLK_HZ           = 24_000_000,
    parameter int unsigned SCAN_HZ          = 200,
    parameter int unsigned SLOT_HZ          = 1_000,
    parameter int unsigned RELEASE_SCANS    = 2,
    parameter bit          SEG_ACTIVE_LOW   = 1'b1,
    parameter bit          DIGIT_ACTIVE_LOW = 1'b1
) (
    input  logic       reset_n,
    input  logic [3:0] row_n,
    output wire  [3:0] col_n,
    output logic [6:0] seg,
    output logic [1:0] digit
);

  logic       clk;
  logic       reset_n_sync;
  logic       rst;
  logic       scan_tick;
  logic [3:0] row_n_sync;
  logic [3:0] col_n_drive;
  logic       key_valid;
  logic [3:0] key_code;
  logic [3:0] hex_old;
  logic [3:0] hex_new;
  logic [6:0] seg_on;
  logic [1:0] digit_on;

  // --- Clock and reset -------------------------------------------------------
  HSOSC #(
      .CLKHF_DIV("0b01")
  ) u_hfosc (
      .CLKHFPU(1'b1),
      .CLKHFEN(1'b1),
      .CLKHF  (clk)
  );

  sync_2ff #(
      .WIDTH(1)
  ) u_rst_sync (
      .clk(clk),
      .d  (reset_n),
      .q  (reset_n_sync)
  );

  assign rst = ~reset_n_sync;

  // --- Keypad ----------------------------------------------------------------
  sync_2ff #(
      .WIDTH(4)
  ) u_row_sync (
      .clk(clk),
      .d  (row_n),
      .q  (row_n_sync)
  );

  tick_gen #(
      .CLK_HZ (CLK_HZ),
      .TICK_HZ(SCAN_HZ)
  ) u_scan_tick (
      .clk (clk),
      .rst (rst),
      .tick(scan_tick)
  );

  keypad_scanner #(
      .RELEASE_SCANS(RELEASE_SCANS)
  ) u_scanner (
      .clk      (clk),
      .rst      (rst),
      .scan_tick(scan_tick),
      .row_n    (row_n_sync),
      .col_n    (col_n_drive),
      .key_valid(key_valid),
      .key_code (key_code)
  );

  for (genvar i = 0; i &lt; 4; i++) begin : g_col_open_drain
    assign col_n[i] = col_n_drive[i] ? 1'bz : 1'b0;
  end

  // --- Key history -----------------------------------------------------------
  always_ff @(posedge clk) begin
    if (rst) begin
      hex_old &lt;= 4'h0;
      hex_new &lt;= 4'h0;
    end else if (key_valid) begin
      hex_old &lt;= hex_new;
      hex_new &lt;= key_code;
    end
  end

  // --- Display ---------------------------------------------------------------
  display_mux #(
      .CLK_HZ (CLK_HZ),
      .SLOT_HZ(SLOT_HZ)
  ) u_display (
      .clk      (clk),
      .rst      (rst),
      .hex_left (hex_old),
      .hex_right(hex_new),
      .seg      (seg_on),
      .digit_en (digit_on)
  );

  assign seg   = SEG_ACTIVE_LOW   ? ~seg_on   : seg_on;
  assign digit = DIGIT_ACTIVE_LOW ? ~digit_on : digit_on;

endmodule









